# Guarda este archivo como api.py y arráncalo con:  uvicorn api:app --reload
import os

import anthropic
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

# La clave de pago nunca se escribe aquí: se lee del entorno (los ajustes que
# guarda el ordenador fuera del código), así no acaba subida a internet sin querer.
API_KEY = os.environ.get("ANTHROPIC_API_KEY")
if not API_KEY:
    raise RuntimeError("Falta ANTHROPIC_API_KEY. Ponla antes de arrancar el servidor.")

cliente = anthropic.Anthropic(api_key=API_KEY)
app = FastAPI(title="Resumidor de textos", version="1.0")


# El molde de lo que aceptamos. Lo que no encaje, FastAPI lo rechaza él solo.
class Peticion(BaseModel):
    texto: str = Field(min_length=20, max_length=8000)
    frases: int = Field(default=3, ge=1, le=10)


class Respuesta(BaseModel):
    resumen: str
    tokens_gastados: int


@app.post("/resumir", response_model=Respuesta)
def resumir(peticion: Peticion):
    try:
        mensaje = cliente.messages.create(
            model="claude-haiku-4-5",
            max_tokens=600,
            system=f"Resume en exactamente {peticion.frases} frases. Sin preámbulo.",
            messages=[{"role": "user", "content": peticion.texto}],
        )
    except anthropic.RateLimitError:
        # Has pedido demasiadas cosas seguidas. Quien te llama puede reintentar.
        raise HTTPException(status_code=429, detail="Demasiadas peticiones, prueba en un minuto.")
    except anthropic.AuthenticationError:
        # Fallo tuyo, no de quien llama: no le cuentes por fuera qué ha pasado.
        raise HTTPException(status_code=500, detail="Error de configuración del servidor.")
    except anthropic.APIError as error:
        raise HTTPException(status_code=502, detail=f"El modelo no ha respondido: {error}")

    return Respuesta(
        resumen=mensaje.content[0].text,
        tokens_gastados=mensaje.usage.input_tokens + mensaje.usage.output_tokens,
    )


@app.get("/salud")
def salud():
    return {"estado": "vivo"}
